const nicheFromWebhook = $('Webhook Trigger: Scrape').item.json.body?.niche || 'general';

return items.map(item => {
  const post = item.json;

  // Threads post ID
  const postId =
    post.id ||
    post.post_id ||
    (post.url || '').match(/\/post\/([A-Za-z0-9_-]+)/)?.[1] ||
    null;

  if (!postId) return null;

  const postUrl = post.url || post.permalink || null;
  const profileUrl = post.ownerProfileUrl || post.profile_url || null;

  const text = (
    post.text ||
    post.caption ||
    post.content ||
    ''
  ).substring(0, 2000);

  const createdAt = post.timestamp || post.created_at || new Date().toISOString();

  function parseCount(v) {
    if (v == null) return 0;
    if (typeof v === 'number') return v;
    const s = String(v).toUpperCase().trim();
    if (s.includes('M')) return parseFloat(s) * 1_000_000;
    if (s.includes('K')) return parseFloat(s) * 1_000;
    const n = parseInt(s.replace(/[^0-9]/g, ''));
    return isNaN(n) ? 0 : n;
  }

  const likeCount = parseCount(post.likeCount || post.like_count || 0);
  const replyCount = parseCount(post.replyCount || post.reply_count || 0);
  const repostCount = parseCount(post.repostCount || post.repost_count || 0);

  // Detect media type and URLs
  const hasVideo = !!(post.videoUrl || post.video_url || (post.media_type === 'video'));
  const videoUrl = post.videoUrl || post.video_url || null;
  const thumbnailUrl = post.thumbnailUrl || post.thumbnail_url || post.displayUrl || null;

  return {
    json: {
      post_id:       String(postId),
      post_url:      postUrl,
      profile_url:   profileUrl,
      username:      post.ownerUsername || post.username || '',
      text:          text,
      created_at:    createdAt,
      like_count:    likeCount,
      reply_count:   replyCount,
      repost_count:  repostCount,
      has_video:     hasVideo,
      video_url:     videoUrl,
      thumbnail_url: thumbnailUrl,
      niche:         nicheFromWebhook,
      status:        'scraped'
    }
  };
}).filter(Boolean);

const webhookData = $('Webhook Trigger: Generate').item.json.body;
const postData = $input.first().json;
return [{ json: {
  post_id:     postData.post_id,
  post_text:   postData.text || '',
  like_count:  postData.like_count || 0,
  reply_count: postData.reply_count || 0,
  repost_count: postData.repost_count || 0,
  has_video:   postData.has_video || false,
  niche:       webhookData.niche || postData.niche || 'general',
  user_id:     webhookData.user_id || 'anonymous',
  user_prompt: webhookData.prompt || ''
}}];

const ctx = $('Merge Context').item.json;
const text = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text?.trim().toLowerCase() || ctx.niche;
const valid = ['tech','cuisine','lifestyle','funny','sport','news','travel','fashion','business','motivation','general'];
return [{ json: { ...ctx, niche: valid.includes(text) ? text : ctx.niche } }];

// ============================================================
// BUILD AI PROMPT — Threads Script + Video Prompt
// Uses Groq (llama-3.3-70b-versatile) — niche-aware & dynamic
// Threads Algorithm: Reposts > Replies > Likes > Watch Completion
// ============================================================

const data = $input.first().json;

const postText    = data.post_text    || '';
const postLikes   = data.like_count   || 0;
const postReplies = data.reply_count  || 0;
const postReposts = data.repost_count || 0;
const postNiche   = data.niche        || 'general';
const userAngle   = data.user_prompt  || '';

const postContext = postText
  ? 'Caption: "' + postText + '"\nLikes: ' + postLikes + ' | Replies: ' + postReplies + ' | Reposts: ' + postReposts + '\nDetected Niche: ' + postNiche
  : 'Post ID: ' + (data.post_id || 'N/A') + '\nLikes: ' + postLikes + '\nDetected Niche: ' + postNiche;

// ── NICHE-SPECIFIC SCRIPT GUIDELINES ───────────────────────
const nicheGuide = {
  funny: {
    hook_style: 'absurd opener ou plot twist — fait rire en 2 sec',
    body_style: 'escalade comique rapide, situation relatable, punch final inattendu',
    cta_style:  'Tague quelqu\'un qui fait ça / Partage si tu te reconnais',
    tone: 'playful, exagéré, autodérision'
  },
  cuisine: {
    hook_style: 'reveal appétissant ou fact food choquant',
    body_style: 'étapes claires, langage sensoriel (croustillant, fondu, doré)',
    cta_style:  'Sauvegarde cette recette / Commente ta version',
    tone: 'chaleureux, appétissant, instructionnel et casual'
  },
  tech: {
    hook_style: 'claim fort sur un outil ou shortcut que personne connaît',
    body_style: 'demo step-by-step, contraste avant/après, temps ou argent économisé',
    cta_style:  'Sauvegarde pour plus tard / Partage avec quelqu\'un qui a besoin',
    tone: 'autoritaire mais accessible, rythme rapide'
  },
  lifestyle: {
    hook_style: 'statement aspirationnel ou moment de routine relatable',
    body_style: 'tip personnel ou mindset shift avec application réelle',
    cta_style:  'Partage avec quelqu\'un qui a besoin de ça / Commente comment tu le fais',
    tone: 'authentique, chaleureux, motivant'
  },
  sport: {
    hook_style: 'stat impressionnante, défi, ou secret d\'entraînement',
    body_style: 'breakdown de drill ou technique, résultats mesurables, langage intensif',
    cta_style:  'Essaie ça aujourd\'hui / Tague ton partenaire d\'entraînement',
    tone: 'haute énergie, motivationnel, concis'
  },
  news: {
    hook_style: 'reveal breaking ou format "ça vient de se passer" urgence',
    body_style: 'résumé 3 points clairs, angle local (Tunisie/monde arabe), pourquoi ça compte',
    cta_style:  'Partage avant qu\'ils suppriment / Commente ta réaction',
    tone: 'sérieux, fiable, punchy'
  },
  travel: {
    hook_style: 'reveal d\'un endroit caché ou opener "arrête de dormir sur ce lieu"',
    body_style: 'mise en scène sensorielle, tips pratiques (coût, meilleure période, comment y aller)',
    cta_style:  'Sauvegarde pour ton prochain voyage / Partage avec qui tu veux emmener',
    tone: 'wanderlust, cinématique, inspirant'
  },
  fashion: {
    hook_style: 'reveal de style inattendu ou combo qui surprend',
    body_style: 'breakdown de la tenue avec pièces key, budget ou dupe accessible',
    cta_style:  'Sauvegarde pour ton prochain outfit / Tague ton ami stylé',
    tone: 'chic, confident, accessible'
  },
  business: {
    hook_style: 'fact contre-intuitif sur le business ou révélation choc sur l\'argent',
    body_style: '3 étapes actionnables, exemple concret, résultat mesurable',
    cta_style:  'Partage avec quelqu\'un qui construit / Sauvegarde et applique',
    tone: 'autoritaire, direct, ambitieux'
  },
  motivation: {
    hook_style: 'vérité universelle qui fait mal ou question qui intrigue',
    body_style: 'histoire courte + leçon + application à la vie réelle',
    cta_style:  'Partage si ça t\'a touché / Commente ton expérience',
    tone: 'inspirant, sincère, puissant'
  },
  general: {
    hook_style: 'curiosity gap ou vérité universelle forte',
    body_style: 'contenu value-driven avec transformation ou insight clair',
    cta_style:  'Partage si tu es d\'accord / Commente ton expérience',
    tone: 'authentique, engageant, universel'
  }
};

const guide = nicheGuide[postNiche] || nicheGuide['general'];

// ── SYSTEM PROMPT ───────────────────────────────────────────
const systemPrompt =
  'You are a dual expert: a Threads viral scriptwriter AND a professional AI video prompt engineer.\n'
  + 'You deeply understand the Threads algorithm (Meta) and write scripts that trigger real engagement.\n\n'

  + '━━━ THREADS ALGORITHM — RANKED SIGNALS ━━━\n'
  + '1. REPOSTS (#1 signal) — content must trigger the "repost to my followers" reflex\n'
  + '2. REPLIES — end with a question or controversial take to boost reach\n'
  + '3. LIKES — emotional resonance or useful insight drives likes\n'
  + '4. WATCH COMPLETION — for video: hook in first 1-2 sec or they scroll\n\n'

  + '━━━ ACTIVE NICHE: ' + postNiche.toUpperCase() + ' ━━━\n'
  + 'Hook style  : ' + guide.hook_style + '\n'
  + 'Body style  : ' + guide.body_style + '\n'
  + 'CTA style   : ' + guide.cta_style  + '\n'
  + 'Tone        : ' + guide.tone       + '\n\n'

  + '━━━ VIRAL HOOK FORMULAS (THREADS) ━━━\n'
  + '- Pattern interrupt : "La vraie raison pourquoi X..." — stops the scroll\n'
  + '- Curiosity gap     : "Ce que personne ne te dit sur X"\n'
  + '- Specific number   : "3 choses que j\'ai testées pendant 7 jours"\n'
  + '- Relatable trap    : "POV: tu fais X et soudain..." — reposté par des milliers\n'
  + '- Local truth       : moment hyper-spécifique Tunisie/monde arabe — max partages communautaires\n'
  + '- Debate bomb       : opinion polarisante — section replies explose\n\n'

  + '━━━ SCRIPT RULES ━━━\n'
  + '1. Hook must stop the scroll in FIRST 1-2 seconds\n'
  + '2. Body delivers REAL value — no fluff, short punchy sentences\n'
  + '3. Every sentence max 10 words — Threads est consommé sur mobile\n'
  + '4. CTA drives REPOSTS or REPLIES, not just follows\n\n'

  + '━━━ VIDEO PROMPT RULES (9:16 · 5-15 seconds) ━━━\n'
  + '1. Choose visual style matching THIS niche (cinematic, motion graphic, hyperrealistic, etc.)\n'
  + '2. Describe 3 beats: second 1 / seconds 2-12 / final second\n'
  + '3. Specify: shot type, subject, action, color palette, lighting, background\n'
  + '4. Nothing vague — every word helps the AI video generator\n\n'

  + 'Return ONLY valid JSON — no markdown, no explanation:\n'
  + '{\n'
  + '  "title"          : "Catchy title for Tunisian/Arab market (Arabic, French, or Darija)",\n'
  + '  "hook"           : "First 1-2 seconds on screen — pattern interrupt or curiosity gap. Max 10 words.",\n'
  + '  "body"           : "Main content 10-30 seconds — real value, short punchy sentences, niche-specific.",\n'
  + '  "cta"            : "Last 3-5 seconds — one clear action that drives REPOSTS or REPLIES",\n'
  + '  "hook_text"      : "On-screen text overlay (same as hook). Max 8 words.",\n'
  + '  "video_prompt"   : "4-sentence AI video prompt. S1: shot type + visual style + 9:16. S2: subject + action at second 1. S3: motion/color/lighting seconds 2-12. S4: payoff at final second + background.",\n'
  + '  "negative_prompt": "Elements to exclude based on chosen style. Always include: text overlay, watermark, distorted faces, grainy, low resolution.",\n'
  + '  "caption"        : "Threads caption — starts with hook, 2-3 lines of value, ends with a question. French/Arabic/Darija.",\n'
  + '  "hashtags"       : ["#Tunisia", "#Threads", "#' + postNiche + '", "#trending", "#viral"],\n'
  + '  "music_vibe"     : "Precise music energy matching tone and visual arc"\n'
  + '}';

const userMessage =
  'TRENDING THREADS POST INSPIRATION:\n'
  + postContext
  + '\n\n'
  + (userAngle ? 'CREATOR SPECIFIC ANGLE: ' + userAngle + '\n' : '')
  + '\n\nStudy this Threads post above. Understand WHY it performed well. Create an ORIGINAL viral Threads video script'
  + ' for the ' + postNiche + ' niche — borrow its virality formula, NOT its words.'
  + ' Write a real script (hook + body + cta) AND a detailed video_prompt for AI video generation.';

return [{
  json: {
    niche:         postNiche,
    postId:        data.post_id,
    userId:        data.user_id,
    userPrompt:    userAngle,
    postContext,
    systemPrompt,
    userMessage
  }
}];

const response = $input.first().json;

const messageContent = response.choices?.[0]?.message?.content || response.output || '';
let scriptJson = {};
try {
  scriptJson = JSON.parse(messageContent);
} catch(e) {
  try {
    const jsonMatch = messageContent.match(/\{[\s\S]*\}/);
    if (jsonMatch) { scriptJson = JSON.parse(jsonMatch[0]); }
  } catch(e2) {
    scriptJson = {
      hook: messageContent, body: '', cta: '',
      hook_text: '', video_prompt: messageContent,
      negative_prompt: 'text overlay, watermark, distorted faces, grainy, low resolution',
      caption: '', hashtags: ['#viral', '#Threads'], music_vibe: 'energetic'
    };
  }
}

const fullScript = [scriptJson.hook, scriptJson.body, scriptJson.cta].filter(Boolean).join('\n\n');
const ctx = $('Merge Context').item.json;

return [{ json: {
  ...ctx,
  script_content:  fullScript,
  script_json:     JSON.stringify(scriptJson),
  hook:            scriptJson.hook            || '',
  body:            scriptJson.body            || '',
  cta:             scriptJson.cta             || '',
  title:           scriptJson.title           || 'Generated Threads Video',
  hook_text:       scriptJson.hook_text       || scriptJson.hook || '',
  video_prompt:    (scriptJson.video_prompt   || '').substring(0, 2500),
  negative_prompt: scriptJson.negative_prompt || 'text overlay, watermark, distorted faces, grainy, low resolution',
  caption:         scriptJson.caption         || '',
  hashtags:        Array.isArray(scriptJson.hashtags) ? scriptJson.hashtags.join(' ') : (scriptJson.hashtags || ''),
  music_vibe:      scriptJson.music_vibe      || '',
  script_text:     fullScript
}}];

